from __future__ import annotations

import io
import os
from dataclasses import dataclass
from typing import Any, Dict, List, Optional, Union

from google.cloud import documentai  # provider-identifying signal: google-cloud-documentai


@dataclass
class OCRLayoutResult:
    blocks: List[Dict[str, Any]]
    lines: List[Dict[str, Any]]
    tables: List[Dict[str, Any]]
    raw_document: Dict[str, Any]


def _bbox_from_layout(layout: Any) -> Optional[Dict[str, Any]]:
    if not layout or not getattr(layout, "bounding_poly", None):
        return None
    vertices = []
    for p in layout.bounding_poly.vertices:
        vertices.append({"x": getattr(p, "x", None), "y": getattr(p, "y", None)})
    return {"vertices": vertices}


def _text_from_layout(layout: Any, text: str) -> str:
    if not layout or not getattr(layout, "text_anchor", None):
        return ""
    parts = []
    for segment in layout.text_anchor.text_segments:
        start = int(segment.start_index) if getattr(segment, "start_index", None) else 0
        end = int(segment.end_index) if getattr(segment, "end_index", None) else len(text)
        parts.append(text[start:end])
    return "".join(parts).strip()


def _serialize_page(page: Any, full_text: str) -> Dict[str, Any]:
    page_out: Dict[str, Any] = {
        "page_number": getattr(page, "page_number", None),
        "dimension": {
            "width": getattr(getattr(page, "dimension", None), "width", None),
            "height": getattr(getattr(page, "dimension", None), "height", None),
            "unit": getattr(getattr(page, "dimension", None), "unit", None),
        },
        "blocks": [],
        "lines": [],
        "tables": [],
    }

    for block in getattr(page, "blocks", []):
        layout = getattr(block, "layout", None)
        page_out["blocks"].append(
            {
                "text": _text_from_layout(layout, full_text),
                "type": getattr(block, "block_type", None),
                "confidence": getattr(block, "confidence", None),
                "bbox": _bbox_from_layout(layout),
            }
        )

    for paragraph in getattr(page, "paragraphs", []):
        layout = getattr(paragraph, "layout", None)
        page_out["blocks"].append(
            {
                "text": _text_from_layout(layout, full_text),
                "type": "paragraph",
                "confidence": getattr(paragraph, "confidence", None),
                "bbox": _bbox_from_layout(layout),
            }
        )

    for line in getattr(page, "lines", []):
        layout = getattr(line, "layout", None)
        page_out["lines"].append(
            {
                "text": _text_from_layout(layout, full_text),
                "confidence": getattr(line, "confidence", None),
                "bbox": _bbox_from_layout(layout),
            }
        )

    for table in getattr(page, "tables", []):
        table_dict: Dict[str, Any] = {
            "confidence": getattr(table, "confidence", None),
            "bbox": _bbox_from_layout(getattr(table, "layout", None)),
            "header_rows": [],
            "body_rows": [],
        }
        for row in getattr(table, "header_rows", []):
            row_cells = []
            for cell in getattr(row, "cells", []):
                layout = getattr(cell, "layout", None)
                row_cells.append(
                    {
                        "text": _text_from_layout(layout, full_text),
                        "row_span": getattr(cell, "row_span", None),
                        "col_span": getattr(cell, "col_span", None),
                        "bbox": _bbox_from_layout(layout),
                    }
                )
            table_dict["header_rows"].append(row_cells)

        for row in getattr(table, "body_rows", []):
            row_cells = []
            for cell in getattr(row, "cells", []):
                layout = getattr(cell, "layout", None)
                row_cells.append(
                    {
                        "text": _text_from_layout(layout, full_text),
                        "row_span": getattr(cell, "row_span", None),
                        "col_span": getattr(cell, "col_span", None),
                        "bbox": _bbox_from_layout(layout),
                    }
                )
            table_dict["body_rows"].append(row_cells)

        page_out["tables"].append(table_dict)

    return page_out


def extract_layout_elements(
    document: Union[str, bytes, bytearray, io.BufferedIOBase],
    project_id: str,
    location: str,
    processor_id: str,
    mime_type: str = "application/pdf",
) -> OCRLayoutResult:
    client = documentai.DocumentProcessorServiceClient()

    processor_name = client.processor_path(project_id, location, processor_id)

    if isinstance(document, str):
        with open(document, "rb") as f:
            content = f.read()
    elif isinstance(document, (bytes, bytearray)):
        content = bytes(document)
    else:
        content = document.read()

    raw_document = documentai.RawDocument(content=content, mime_type=mime_type)
    request = documentai.ProcessRequest(name=processor_name, raw_document=raw_document)

    result = client.process_document(request=request)
    doc = result.document

    full_text = getattr(doc, "text", "") or ""

    blocks: List[Dict[str, Any]] = []
    lines: List[Dict[str, Any]] = []
    tables: List[Dict[str, Any]] = []

    for page in getattr(doc, "pages", []):
        serialized = _serialize_page(page, full_text)
        blocks.extend(serialized["blocks"])
        lines.extend(serialized["lines"])
        tables.extend(serialized["tables"])

    raw_document_dict = documentai.Document.to_dict(doc)

    return OCRLayoutResult(
        blocks=blocks,
        lines=lines,
        tables=tables,
        raw_document=raw_document_dict,
    )


def extract_blocks_lines_tables(
    document: Union[str, bytes, bytearray, io.BufferedIOBase],
    project_id: Optional[str] = None,
    location: Optional[str] = None,
    processor_id: Optional[str] = None,
    mime_type: str = "application/pdf",
) -> Dict[str, Any]:
    project_id = project_id or os.environ.get("GOOGLE_CLOUD_PROJECT") or os.environ.get("GCP_PROJECT")
    location = location or os.environ.get("DOCUMENT_AI_LOCATION", "us")
    processor_id = processor_id or os.environ.get("DOCUMENT_AI_PROCESSOR_ID")

    if not project_id:
        raise ValueError("project_id is required or must be set via GOOGLE_CLOUD_PROJECT/GCP_PROJECT.")
    if not processor_id:
        raise ValueError("processor_id is required or must be set via DOCUMENT_AI_PROCESSOR_ID.")

    result = extract_layout_elements(
        document=document,
        project_id=project_id,
        location=location,
        processor_id=processor_id,
        mime_type=mime_type,
    )

    return {
        "blocks": result.blocks,
        "lines": result.lines,
        "tables": result.tables,
        "raw_document": result.raw_document,
    }
